const files = ['memoria.md','STATUS.md','QUESTIONS.md','PERGUNTAS.md'].map(f=>[f, txt('/work/workspace/deliverable/'+f)]);
function allHave(s){ return files.filter(([,t])=>!t.includes(s)).map(([f])=>f); }

return {
